/bin/zsh -c "python3 -c 'import sympy as s, math; from scipy.special import zeta; P=list(s.primerange(2,1000001));
for name in [\"k"'^2+1","k''^3+2","2k+1"]:
 L=1.
 for p in P:
  if name=="k''^2+1": r=1 if p==2 else (2 if p%4==1 else 0); r2=0 if p==2 else r
  elif name=="k''^3+2": r=1 if p in (2,3) or p%3==2 else (3 if pow(p-2,(p-1)//3,p)==1 else 0); r2=0 if p in (2,3) else r
  else: r=0 if p==2 else 1; r2=r
  a=1-2/p**2+r2/p**4; u=r/p**3-r2/p**4; v=1/p**2-r/p**3; L*=(1-1/p)*(a+math.sqrt(p)*u+p*v)
  if p in (99991,999983): print(name,p,2*zeta(1.5,1)/(3*math.pi)*L)
'"'"

